/**
 * Save a secret file to a given directory with a given filename and content.
 * The file should be accessible only by the current user.
 *
 * @param {string} directory - The directory to save the secret file.
 * @param {string} filename - The filename of the secret file.
 * @param {string} content - The content of the secret file.
 */
function saveSecretFile(directory, filename, content) {
  const fs = require('fs');
  const path = require('path');

  // Validate directory path
  if (!path.isAbsolute(directory)) {
    throw new Error('Directory must be an absolute path');
  }

  // Normalize the directory path to avoid issues with relative paths
  const normalizedDirectory = path.resolve(directory);

  // Validate filename to prevent directory traversal
  if (path.isAbsolute(filename) || filename.includes('../') || filename.includes('..')) {
    throw new Error('Invalid filename');
  }

  // Ensure the directory exists
  try {
    fs.accessSync(normalizedDirectory, fs.constants.F_OK);
  } catch (err) {
    throw new Error('Directory does not exist');
  }

  const filePath = path.join(normalizedDirectory, filename);

  try {
    fs.writeFileSync(filePath, content, { mode: 0o600 });
  } catch (err) {
    throw new Error(`Failed to write file: ${err.message}`);
  }
}
